CREATE TABLE IF NOT EXISTS customers(id VARCHAR(32) PRIMARY KEY,name VARCHAR(200) NOT NULL,inn VARCHAR(32),address VARCHAR(300),phone VARCHAR(80),kind VARCHAR(80));
CREATE TABLE IF NOT EXISTS products(id INT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS materials(id INT PRIMARY KEY,name VARCHAR(200) NOT NULL,unit VARCHAR(30) NOT NULL,price DECIMAL(14,4) NOT NULL CHECK(price>=0));
CREATE TABLE IF NOT EXISTS operations(id INT PRIMARY KEY,name VARCHAR(200) NOT NULL,rate_hour DECIMAL(14,4) NOT NULL CHECK(rate_hour>=0));
CREATE TABLE IF NOT EXISTS material_norms(product_id INT NOT NULL,material_id INT NOT NULL,norm DECIMAL(14,6) NOT NULL CHECK(norm>0),PRIMARY KEY(product_id,material_id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(material_id) REFERENCES materials(id));
CREATE TABLE IF NOT EXISTS operation_norms(product_id INT NOT NULL,operation_id INT NOT NULL,hours DECIMAL(14,6) NOT NULL CHECK(hours>0),PRIMARY KEY(product_id,operation_id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(operation_id) REFERENCES operations(id));
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,login VARCHAR(64) NOT NULL UNIQUE,password_hash VARCHAR(300) NOT NULL,full_name VARCHAR(160) NOT NULL,role ENUM('Administrator','User') NOT NULL,failed_attempts INT NOT NULL DEFAULT 0 CHECK(failed_attempts BETWEEN 0 AND 3),blocked BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,customer_id VARCHAR(32) NOT NULL,created_by INT NOT NULL,status ENUM('Новый','В производстве','Завершён') NOT NULL DEFAULT 'Новый',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS order_lines(order_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL CHECK(quantity>0),PRIMARY KEY(order_id,product_id),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS order_audit(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production_orders(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL UNIQUE,launch_date DATE NOT NULL,department VARCHAR(160) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id));
